  'Go to Upload, choose your video file, add required details, select category and language, add a thumbnail, then publish. Large files upload in chunks.' => 'अपलोड पर जाएं, अपनी वीडियो फ़ाइल चुनें, आवश्यक विवरण जोड़ें, श्रेणी और भाषा चुनें, एक थंबनेल जोड़ें, फिर प्रकाशित करें। बड़ी फ़ाइलें टुकड़ों में अपलोड होती हैं.',
  'Guest mode' => 'अतिथि विधा',
  'Have a question, feedback, partnership idea, or support request? Send it through the backend form and admins will see it in the Support dashboard.' => 'क्या आपके पास कोई प्रश्न, प्रतिक्रिया, साझेदारी विचार या समर्थन अनुरोध है? इसे बैकएंड फॉर्म के माध्यम से भेजें और व्यवस्थापक इसे समर्थन डैशबोर्ड में देखेंगे।',
