  'If no paid transaction exists in the connected billing provider or platform records, there is no platform charge to refund. Refunds can only be reviewed against payment records, subscription IDs, invoices, or transaction references.' => 'यदि कनेक्टेड बिलिंग प्रदाता या प्लेटफ़ॉर्म रिकॉर्ड में कोई भुगतान किया गया लेनदेन मौजूद नहीं है, तो धनवापसी के लिए कोई प्लेटफ़ॉर्म शुल्क नहीं है। रिफंड की समीक्षा केवल वास्तविक भुगतान रिकॉर्ड, सदस्यता आईडी, चालान या लेनदेन संदर्भों के आधार पर की जा सकती है।',
