  'Official contact addresses, billing contacts, and external support channels should be configured by the PlayHub site administrator for this deployment. This page intentionally does not display unverified email addresses.' => 'इस परिनियोजन के लिए आधिकारिक संपर्क पते, बिलिंग संपर्क और बाहरी समर्थन चैनल को PlayHub साइट व्यवस्थापक द्वारा कॉन्फ़िगर किया जाना चाहिए। यह पृष्ठ जानबूझकर असत्यापित ईमेल पते प्रदर्शित नहीं करता है।',
  'On this page' => 'इस पेज पर',
  'Open Help Center' => 'सहायता केंद्र खोलें',
  'Open settings' => 'सेटिंग्स खोलें',
  'Open Settings, go to Security, then use the password or two-factor dialog. Two-factor delivery supports email or phone when configured.' => 'सेटिंग्स खोलें, सिक्योरिटी पर जाएं, फिर पासवर्ड या टू-फैक्टर डायलॉग का उपयोग करें। कॉन्फ़िगर होने पर दो-कारक डिलीवरी ईमेल या फ़ोन का समर्थन करती है।',
  'Operational snapshot' => 'ऑपरेशनल स्नैपशॉट',
  'Optional, but recommended' => 'वैकल्पिक, लेकिन अनुशंसित',
  'Other' => 'अन्य',
  'Partnerships, press, and platform operations.' => 'साझेदारी, प्रेस और मंच संचालन।',
  'Payment help' => 'भुगतान सहायता',
  'Platform' => 'मंच',
  'Playback' => 'प्लेबैक',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'प्रमाणित प्लेटफ़ॉर्म सुविधाओं से लिंक होने पर प्लेबैक प्रगति, बाद में देखने की स्थिति, पसंद, टिप्पणियां, सदस्यता, सूचनाएं और व्यवस्थापक विश्लेषण डेटाबेस में संग्रहीत किए जाते हैं।',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'प्लेबैक, टिप्पणियाँ, पसंद, बाद में देखें, सदस्यताएँ, सूचनाएं, संदेश, प्लेलिस्ट और भाषा सेटिंग्स मुख्य नेविगेशन और खाता मेनू के माध्यम से उपलब्ध हैं।',
  'PlayHub' => 'प्लेहब',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub एक खाते से निर्माता सामग्री को अपलोड करने, देखने, शेड्यूल करने, प्रबंधित करने और मॉडरेट करने के लिए एक वीडियो प्लेटफ़ॉर्म है।',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub इस परिनियोजन पर चलने वाला वीडियो प्लेटफ़ॉर्म है, जो रचनाकारों, दर्शकों, समुदायों और प्लेटफ़ॉर्म ऑपरेटरों के लिए बनाया गया है।',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub एक ही मंच से निर्माता चैनल, वीडियो अपलोड, निर्धारित प्रकाशन, सदस्यता, टिप्पणियाँ, प्लेलिस्ट, बाद में देखें, लाइव सामग्री पृष्ठ और प्रशासन उपकरण प्रदान करता है।',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub लॉगिन सत्र, एपीआई प्रमाणीकरण, सीएसआरएफ/सुरक्षा व्यवहार, भाषा चयन, थीम चयन, खाता मेनू स्थिति और एप्लिकेशन के काम करने के लिए आवश्यक अन्य सुविधाओं के लिए आवश्यक कुकीज़ और ब्राउज़र स्टोरेज का उपयोग करता है।',
  'playhub_language, theme' => 'प्लेहब_लैंग्वेज, थीम',
  'Popular questions' => 'लोकप्रिय प्रश्न',
  'Preference storage' => 'प्राथमिकता भंडारण',
  'Privacy Policy' => 'गोपनीयता नीति',
  'Privacy, cookie, account security, support messages, and moderation data are handled through the policies and backend records connected to PlayHub.' => 'गोपनीयता, कुकी, खाता सुरक्षा, समर्थन संदेश और मॉडरेशन डेटा को PlayHub से जुड़ी नीतियों और बैकएंड रिकॉर्ड के माध्यम से नियंत्रित किया जाता है।',
  'Profile, login, security, and settings help.' => 'प्रोफ़ाइल, लॉगिन, सुरक्षा और सेटिंग्स सहायता।',
  'Profile, security, and preferences.' => 'प्रोफ़ाइल, सुरक्षा और प्राथमिकताएँ.',
  'Public API route' => 'सार्वजनिक एपीआई मार्ग',
  'Public JSON endpoints include /api/health for deployment status and /api/upload-options for upload categories, languages, limits, chunk size, and trending tags.' => 'सार्वजनिक JSON एंडपॉइंट में परिनियोजन स्थिति के लिए /api/health और अपलोड श्रेणियों, भाषाओं, सीमाओं, खंड आकार और ट्रेंडिंग टैग के लिए /api/upload-विकल्प शामिल हैं।',
  'Public REST API' => 'सार्वजनिक रेस्ट एपीआई',
