  'Refund' => 'वापसी',
  'Refund and paid feature guidance.' => 'धनवापसी और भुगतान सुविधा मार्गदर्शन।',
  'Refund handling for paid PlayHub features depends on billing records attached to this deployment.' => 'सशुल्क PlayHub सुविधाओं के लिए रिफंड प्रबंधन इस परिनियोजन से जुड़े वास्तविक बिलिंग रिकॉर्ड पर निर्भर करता है।',
  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'रिफंड प्रबंधन वास्तविक बिलिंग रिकॉर्ड और प्रशासक समीक्षा से जुड़ा हुआ है। यदि इस परिनियोजन के लिए बिलिंग कॉन्फ़िगर नहीं की गई है, तो धनवापसी के लिए कोई प्लेटफ़ॉर्म शुल्क नहीं है।',
  'Refund issued' => 'रिफंड जारी किया गया',
