  'Reports, moderation, and privacy.' => 'रिपोर्ट, मॉडरेशन और गोपनीयता।',
  'Reports, moderation, privacy, and community safety.' => 'रिपोर्ट, मॉडरेशन, गोपनीयता और सामुदायिक सुरक्षा।',
  'Request a refund' => 'धनवापसी का अनुरोध करें',
  'Required' => 'आवश्यक',
  'Required for login, security, and app routing.' => 'लॉगिन, सुरक्षा और ऐप रूटिंग के लिए आवश्यक है।',
