  'Review privacy and cookie details for this deployment.' => 'इस परिनियोजन के लिए गोपनीयता और कुकी विवरण की समीक्षा करें।',
  'Rules for using this PlayHub deployment as a viewer, creator, or administrator.' => 'एक दर्शक, निर्माता या व्यवस्थापक के रूप में इस PlayHub परिनियोजन का उपयोग करने के नियम।',
