  'Safety and content reports' => 'सुरक्षा और सामग्री रिपोर्ट',
  'Safety or report' => 'सुरक्षा या रिपोर्ट',
  'Sample endpoints' => 'नमूना समापनबिंदु',
  'sample endpoints loaded' => 'नमूना समापनबिंदु लोड किया गया',
  'Schedule video' => 'वीडियो शेड्यूल करें',
  'Scheduled video release and reminders.' => 'शेड्यूल किया गया वीडियो रिलीज़ और अनुस्मारक.',
  'Scheduled videos' => 'शेड्यूल किए गए वीडियो',
  'Scheduling a video release' => 'वीडियो रिलीज़ शेड्यूल करना',
  'Search for answers...' => 'उत्तर खोजें...',
  'Search help articles, topics, or questions...' => 'सहायता लेख, विषय या प्रश्न खोजें...',
  'Select a reason' => 'एक कारण चुनें',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'एक या अधिक वीडियो फ़ाइलें चुनें, आवश्यक विवरण दर्ज करें, श्रेणी और भाषा चुनें, एक थंबनेल जोड़ें, दृश्यता चुनें और प्रकाशित करें। सर्वर द्वारा प्रोसेसिंग शुरू करने से पहले बड़ी फ़ाइलों को टुकड़ों में अपलोड किया जाता है।',
  'Send a message and it will be saved for admins.' => 'एक संदेश भेजें और यह व्यवस्थापकों के लिए सहेजा जाएगा।',
  'Send billing details to admin support for review.' => 'समीक्षा के लिए बिलिंग विवरण व्यवस्थापक सहायता को भेजें।',
  'Send message' => 'संदेश भेजें',
  'Send order details through the refund popup.' => 'रिफंड पॉपअप के माध्यम से ऑर्डर विवरण भेजें।',
  'Send us a message' => 'हमें एक संदेश भेजें',
  'Sending...' => 'भेजा जा रहा है...',
  'Server configured' => 'सर्वर कॉन्फ़िगर किया गया',
  'server records' => 'सर्वर रिकॉर्ड',
  'Service operation' => 'सेवा संचालन',
  'session, token' => 'सत्र, टोकन',
  'Settings and login' => 'सेटिंग्स और लॉगिन',
  'Short summary' => 'संक्षिप्त सारांश',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'साइन इन करें और खाता, प्रोफ़ाइल, पासवर्ड, अधिसूचना, गोपनीयता और निर्माता प्राथमिकताओं के लिए सेटिंग्स का उपयोग करें। निर्माता अपलोड और सामग्री संबंधी मुद्दों में वीडियो शीर्षक, चैनल, ब्राउज़र और अपलोड पृष्ठ पर दिखाई गई कोई भी प्रसंस्करण त्रुटि शामिल होनी चाहिए।',
  'Sign in for account support' => 'खाता समर्थन के लिए साइन इन करें',
  'Signed in' => 'साइन इन किया गया',
  'Start uploading' => 'अपलोड करना प्रारंभ करें',
  'Still can’t find an answer?' => 'अभी भी कोई उत्तर नहीं मिल सका?',
  'Stored for admins' => 'व्यवस्थापकों के लिए संग्रहीत',
  'Stores language, theme, and interface preferences.' => 'भाषा, थीम और इंटरफ़ेस प्राथमिकताओं को संग्रहीत करता है।',
  'Studio, playlists, analytics, channels.' => 'स्टूडियो, प्लेलिस्ट, एनालिटिक्स, चैनल।',
  'Submit a billing or refund message to admin support.' => 'व्यवस्थापक सहायता को बिलिंग या धनवापसी संदेश सबमिट करें।',
  'Submit refund request' => 'धनवापसी अनुरोध सबमिट करें',
  'Submit request' => 'अनुरोध सबमिट करें',
  'Subscription cancellation' => 'सदस्यता रद्दीकरण',
  'Support dashboard' => 'डैशबोर्ड का समर्थन करें',
  'System status' => 'सिस्टम स्थिति',
  'Table' => 'टेबल',
  'Taxonomies' => 'वर्गीकरण',
  'Technical issue' => 'तकनीकी मुद्दा',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'वर्तमान PlayHub API और अपलोड वर्कफ़्लो के साथ एकीकरण के लिए तकनीकी नोट्स।',
  'Tell us more about your question or request...' => 'अपने प्रश्न या अनुरोध के बारे में हमें और बताएं...',
  'Terms of Use' => 'उपयोग की शर्तें',
  'The configured' => 'विन्यस्त',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'डेवलपर पेज लाइव लारवेल बैकएंड से जुड़ा है: रूट इन्वेंट्री, डेटाबेस गणना, अपलोड सीमाएं और प्लेटफ़ॉर्म मेटाडेटा /एपीआई/डेवलपर्स से लोड किए जाते हैं।',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'फ्रंटएंड चयनित भाषा, विषय, प्लेबैक कतार, देखने की प्रगति और इंटरफ़ेस स्थिति जैसी प्राथमिकताओं को संग्रहीत करता है ताकि अनुभव पृष्ठ नेविगेशन और पुनः लोड के दौरान सुसंगत बना रहे।',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'प्रसंस्करण कार्य प्रस्तुतियों को एनकोड करता है, जरूरत पड़ने पर थंबनेल बनाता है, कैप्शन संग्रहीत करता है, और प्रसंस्करण पूरा होने पर वीडियो को तैयार चिह्नित करता है। भविष्य में शेड्यूल किए गए वीडियो तब तक निजी रहते हैं जब तक शेड्यूलर उन्हें रिलीज़ नहीं कर देता।',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'अपलोड सिस्टम डेटाबेस-समर्थित है, एपीआई से श्रेणियों और भाषाओं का समर्थन करता है, अपलोड किए गए वीडियो को संसाधित करता है, थंबनेल और कैप्शन संग्रहीत करता है, और शेड्यूल की गई सामग्री को उसके रिलीज़ होने तक निजी रखता है।',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'यह पृष्ठ बताता है कि PlayHub सत्रों, सुरक्षा, प्राथमिकताओं, प्लेबैक और प्रमाणित सुविधाओं के लिए कुकीज़ और ब्राउज़र संग्रहण का उपयोग कैसे करता है।',
  'Ticket source' => 'टिकट स्रोत',
  'Top content categories' => 'शीर्ष सामग्री श्रेणियाँ',
  'Topic' => 'विषय',
  'Transaction / invoice' => 'लेन-देन/चालान',
  'Transaction / invoice ID' => 'लेनदेन/चालान आईडी',
  'Unable to send message.' => 'संदेश भेजने में असमर्थ.',
  'Unable to submit refund request.' => 'धनवापसी अनुरोध सबमिट करने में असमर्थ.',
  'Understanding admin support tickets' => 'व्यवस्थापक सहायता टिकटों को समझना',
  'Upload and processing help' => 'अपलोड और प्रसंस्करण सहायता',
  'Upload chunks' => 'भाग अपलोड करें',
  'Upload issues' => 'मुद्दे अपलोड करें',
  'Upload languages' => 'भाषाएँ अपलोड करें',
  'Upload limit' => 'अपलोड सीमा',
  'Upload options' => 'विकल्प अपलोड करें',
  'Upload or processing' => 'अपलोड या प्रसंस्करण',
  'Upload page' => 'पेज अपलोड करें',
  'Upload pipeline' => 'पाइपलाइन अपलोड करें',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'लाइव प्लेहब डेटा के साथ अपलोड करें, देखें, सदस्यता लें, मॉडरेट करें और निर्माण करें।',
  'Uploaded videos' => 'अपलोड किए गए वीडियो',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'अपलोड किए गए वीडियो को चलाने योग्य प्रस्तुतियों में एन्कोड किया गया है। प्रसंस्करण समय फ़ाइल आकार, अवधि, सर्वर लोड और कतार स्थिति पर निर्भर करता है। अपलोड पृष्ठ और क्रिएटर स्टूडियो वीडियो रिकॉर्ड से वास्तविक प्रसंस्करण स्थिति दिखाते हैं।',
  'Uploads, scheduling, and processing are available.' => 'अपलोड, शेड्यूलिंग और प्रोसेसिंग उपलब्ध हैं।',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'क्रिएटर वर्कफ़्लो के लिए /api/videos, चैनल एंडपॉइंट और प्रमाणित मार्गों का उपयोग करें।',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'वीडियो और टिप्पणियों के लिए अंतर्निहित रिपोर्ट कार्रवाइयों का उपयोग करें ताकि व्यवस्थापकों को सटीक सामग्री संदर्भ प्राप्त हो सके। व्यवस्थापक डैशबोर्ड पृष्ठ उपयोगकर्ताओं, सामग्री, रिपोर्ट, मुद्रीकरण, विश्लेषण, समर्थन, भूमिका और सिस्टम सेटिंग्स के लिए लाइव डेटाबेस डेटा का उपयोग करते हैं।',
  'Use Contact Us' => 'हमसे संपर्क करें का प्रयोग करें',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'सामान्य एपीआई अनुरोधों के लिए JSON और फ़ाइल अपलोड के लिए फॉर्मडेटा का उपयोग करें। सत्यापन को बायपास न करें: श्रेणियां और भाषाएं डेटाबेस आईडी हैं, दृश्यता सार्वजनिक, असूचीबद्ध या निजी तक सीमित है, और कैप्शन एसआरटी, वीटीटी, या टीएक्सटी फ़ाइलों को स्वीकार करते हैं।',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'अपनी प्रोफ़ाइल, सुरक्षा, पासवर्ड, दो-कारक डिलीवरी, डिवाइस, प्राथमिकताएं और अधिसूचना विकल्प अपडेट करने के लिए सेटिंग्स का उपयोग करें। यदि आप अपने खाते तक नहीं पहुंच सकते हैं, तो लॉगिन प्रवाह का उपयोग करें और साइट व्यवस्थापक को खाता ईमेल प्रदान करें।',
  'Use the contact form' => 'संपर्क फ़ॉर्म का उपयोग करें',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'वीडियो, टिप्पणियों और सामुदायिक पोस्ट पर रिपोर्ट क्रियाओं का उपयोग करें ताकि व्यवस्थापकों को सटीक सामग्री संदर्भ प्राप्त हो सके।',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'जब सामग्री प्लेटफ़ॉर्म नियमों का उल्लंघन कर सकती है तो वीडियो, टिप्पणियों और सामुदायिक पोस्ट पर रिपोर्ट कार्रवाइयों का उपयोग करें। ये रिपोर्टें वास्तविक सामग्री रिकॉर्ड से जुड़ी होती हैं और सामान्य संदेश से बेहतर होती हैं क्योंकि प्रशासक सटीक आइटम की समीक्षा कर सकते हैं।',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'खाता सहायता, सामग्री रिपोर्ट, तकनीकी समस्याओं और व्यवस्थापक अनुरोधों के लिए सही PlayHub चैनल का उपयोग करें।',
  'Video categories' => 'वीडियो श्रेणियां',
  'Video for everyone. Built for creators and viewers.' => 'सभी के लिए वीडियो. वास्तविक प्लेटफ़ॉर्म डेटा से निर्मित।',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'वीडियो अपलोड, शेड्यूलिंग, थंबनेल और प्रोसेसिंग समस्याएं।',
  'Videos, thumbnails, captions, processing.' => 'वीडियो, थंबनेल, कैप्शन, प्रसंस्करण।',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'दर्शक श्रेणियां ब्राउज़ कर सकते हैं, वीडियो खोज सकते हैं, सामग्री देख सकते हैं, चैनलों की सदस्यता ले सकते हैं, बाद में देखने के लिए वीडियो सहेज सकते हैं, टिप्पणी कर सकते हैं, सूचनाएं प्राप्त कर सकते हैं और भाषा और पहुंच संबंधी प्राथमिकताएं प्रबंधित कर सकते हैं।',
  'Viewing and community help' => 'देखना और सामुदायिक सहायता',
  'Waiting for backend endpoint inventory.' => 'बैकएंड एंडपॉइंट इन्वेंट्री की प्रतीक्षा की जा रही है।',
  'We’re here to help.' => 'हम मदद के लिए यहां हैं।',
  'What is PlayHub?' => 'प्लेहब क्या है?',
  'What PlayHub does' => 'प्लेहब क्या करता है',
  'Where do contact messages go?' => 'संपर्क संदेश कहाँ जाते हैं?',
  'Why is my video still processing?' => 'मेरा वीडियो अभी भी संसाधित क्यों हो रहा है?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'हाँ। अपलोड पृष्ठ पर मूल शेड्यूल दिनांक और समय फ़ील्ड का उपयोग करें। बैकएंड शेड्यूल_एट को संग्रहीत करता है, वीडियो को संसाधित करता है, भविष्य की तारीख होने पर इसे निजी रखता है, और जब लारवेल शेड्यूलर निर्धारित समय के बाद चलता है तो इसे जारी करता है।',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'हाँ। अपलोड पर मूल शेड्यूल फ़ील्ड का उपयोग करें। बैकएंड शेड्यूल_एट को संग्रहीत करता है और शेड्यूल समय पूरा होने पर प्रसंस्करण के बाद वीडियो जारी करता है।',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'आप अतिथि के रूप में ब्राउज़ कर रहे हैं. खाता-विशिष्ट टूल तक पहुंचने के लिए साइन इन करें।',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'आप अपने खाते के क्रेडेंशियल्स, प्रोफ़ाइल गतिविधि, अपलोड की गई सामग्री, टिप्पणियों, संदेशों और अपने खाते से किए गए किसी भी निर्माता या व्यवस्थापक कार्यों के लिए जिम्मेदार हैं। मजबूत पासवर्ड का उपयोग करें और दो-कारक वितरण विधियों को चालू रखें।',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'आप अपनी ब्राउज़र सेटिंग में ब्राउज़र कुकीज़ और स्थानीय संग्रहण साफ़ कर सकते हैं। आवश्यक संग्रहण साफ़ करने से आप साइन आउट हो सकते हैं, भाषा/थीम प्राथमिकताएँ रीसेट हो सकती हैं, स्थानीय प्लेबैक स्थिति हट सकती है और आपको फिर से लॉग इन करना पड़ सकता है।',
  'You receive a response by email.' => 'आपको ईमेल द्वारा प्रतिक्रिया प्राप्त होती है.',
  'You’re in control' => 'आप नियंत्रण में हैं',
  'Your choices' => 'आपकी पसंद',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'आपका संदेश सीधे वेबसाइट बैकएंड में सहेजा जाता है और समर्थन के अंतर्गत व्यवस्थापक डैशबोर्ड में दिखाई देता है।',
