  'Publish consistently' => 'लगातार प्रकाशित करें',
  'Upload your first video and give viewers a clear reason to subscribe.' => 'अपना पहला वीडियो अपलोड करें और दर्शकों को सदस्यता लेने का स्पष्ट कारण बताएं।',
  'Use Shorts for discovery' => 'खोज के लिए शॉर्ट्स का उपयोग करें',
  'Keep testing quick hooks and link viewers to longer videos.' => 'त्वरित हुक का परीक्षण करते रहें और दर्शकों को लंबे वीडियो से जोड़ें।',
  'Create short vertical videos to reach viewers who have not found your channel yet.' => 'उन दर्शकों तक पहुंचने के लिए छोटे लंबवत वीडियो बनाएं जिन्हें अभी तक आपका चैनल नहीं मिला है।',
  'Create short' => 'संक्षिप्त बनाएं',
  'Turn comments into loyalty' => 'टिप्पणियों को वफादारी में बदलें',
  'Reply to recent comments and turn viewers into returning fans.' => 'हाल की टिप्पणियों का उत्तर दें और दर्शकों को लौटने वाले प्रशंसकों में बदल दें।',
  'Ask a question in your next upload and reply quickly when comments arrive.' => 'अपने अगले अपलोड में एक प्रश्न पूछें और टिप्पणियाँ आने पर तुरंत उत्तर दें।',
  'View comments' => 'टिप्पणियाँ देखें',
  'Improve public reach' => 'सार्वजनिक पहुंच में सुधार करें',
  'Keep strong videos visible and refresh weak titles.' => 'मजबूत वीडियो को दृश्यमान रखें और कमजोर शीर्षकों को ताज़ा करें।',
  'Explore tools' => 'टूल एक्सप्लोर करें',
