  'Upload planner' => 'अपलोड प्लानर',
  'Start a new upload with titles, tags, visibility, and thumbnail steps.' => 'शीर्षक, टैग, दृश्यता और थंबनेल चरणों के साथ एक नया अपलोड शुरू करें।',
