  'Content manager' => 'सामग्री प्रबंधक',
  'Review visibility, monetization, comments, and performance in one place.' => 'एक ही स्थान पर दृश्यता, मुद्रीकरण, टिप्पणियों और प्रदर्शन की समीक्षा करें।',
  'Analytics review' => 'एनालिटिक्स समीक्षा',
